<?php $movies=$movies??[];$meta=$meta??[];$page=$page??1;$title=$title??'Tất cả phim';$kind=$kind??'all';$pathImage=$pathImage??'';?>
<div class="container" style="padding-top:10px"><div class="fm-section"><div class="fm-bar"><h2><?=e($title)?></h2><span>API: <?=number_format((int)($meta['total']??0))?> phim · Trang <?=e((string)($meta['page']??$page))?> / <?=e((string)($meta['pages']??1))?></span></div><div class="fm-filter"><a class="<?=$kind==='all'&&!($_GET['sort']??'')?'active':''?>" href="<?=e(site('browse.php'))?>">Tất cả</a><a href="<?=e(site('browse.php?type=Phim%20l%E1%BA%BB'))?>">Phim lẻ</a><a href="<?=e(site('browse.php?type=Phim%20b%E1%BB%99'))?>">Phim bộ</a><a href="<?=e(site('browse.php?type=Ho%E1%BA%A1t%20h%C3%ACnh'))?>">Hoạt hình</a><a href="<?=e(site('browse.php?sort=views'))?>">Xem nhiều</a></div>
<?php if($movies): ?><div class="fm-grid"><?php foreach($movies as $m):$poster=(string)($m['poster_url']??$m['thumb_url']??'');$ep=(int)($m['episode_total']??$m['episodes_count']??0);?><article class="fm-card"><a href="<?=e(site('watch.php?slug='.urlencode((string)$m['slug'])))?>"><div class="fm-poster"><img loading="lazy" src="<?=e(img($poster,$pathImage))?>" alt="<?=e($m['name']??'')?>" onerror="this.onerror=null;this.src='<?=e(site('assets/placeholder.svg'))?>'"><span class="fm-quality"><?=e($m['quality']??'HD')?></span><?php if($ep): ?><span class="fm-ep"><?=e((string)$ep)?> tập</span><?php endif;?></div><div class="fm-title"><?=e($m['name']??'')?></div><div class="fm-origin"><?=e($m['origin_name']??'')?></div></a></article><?php endforeach; ?></div><div class="fm-pagination"><?php if($page>1): ?><a href="<?=e(site('browse.php?'.http_build_query(array_merge($_GET,['page'=>$page-1]))))?>">←</a><?php endif;?><?php $from=max(1,(int)$page-2);$to=min((int)($meta['pages']??1),(int)$page+2);for($i=$from;$i<=$to;$i++):?><a class="<?=$i===$page?'active':''?>" href="<?=e(site('browse.php?'.http_build_query(array_merge($_GET,['page'=>$i]))))?>"><?=$i?></a><?php endfor;?><?php if($page<(int)($meta['pages']??1)): ?><a href="<?=e(site('browse.php?'.http_build_query(array_merge($_GET,['page'=>$page+1]))))?>">→</a><?php endif;?></div><?php else: ?><div class="empty">API chưa trả về phim cho mục này.</div><?php endif;?></div></div>
